    EmbeddedChannel channel = new EmbeddedChannel(new HttpResponseDecoder());
    String responseWithIllegalChunk =
            "HTTP/1.1 200 OK\r\n" +
            "Transfer-Encoding: chunked\r\n\r\n" +
            "\0\r\n";

