	AssertJUnit.assertEquals(Arrays.toString(new Object[] { "hello", "world"}), s2);
	String s3 = com.ibm.j9.jsr292.indyn.GenIndyn.bsm_signature_L_S_MT_obj_array_passing_primitives();
