    CurrentUnitOfWork.set(unitOfWork);
    // Back in the context
    assertEquals(10, testSubject.readEvents(aggregateId).asStream().count());
    unitOfWork.rollback();

    assertEquals(2, testSubject.readEvents(aggregateId).asStream().count());
}

