            i32buf[idx++] = (byte) ((n & 0x7F) | 0x80);
            // writeByteDirect((byte)((n & 0x7F) | 0x80));
            n >>>= 7;
        }
    }
    buf.writeBytes(i32buf, 0, idx);
}

